    Verify Preorder Serialization of a Binary Tree

Verify Preorder Serialization of a Binary Tree

diff --git a/tree/331.cc b/tree/331.cc
--- a/tree/331.cc
+++ b/tree/331.cc
@@ -0,0 +1,25 @@
+class Solution {
+public:
+    bool isValidSerialization(string preorder) {
+        int diff = 1;
+        std::string temp = "";
+        for (const auto &c : preorder) {
+            if (c == ',') {
+                --diff;
+                if (diff < 0)
+                    return false;
+                if (temp != "#")
+                    diff += 2;
+                temp = "";
+            } else {
+                temp += c;
+            }
+        }
+        --diff;
+        if (diff < 0)
+            return false;
+        if (temp != "#")
+            diff += 2;        
+        return diff == 0;
+    }
+};

