// src/System/Drawing/Slugifier.ts
import * as Transliteration from "transliteration";

/**
 * Provides the functionality to generate slugs.
 */
export class Slugifier
{
    /**
     * The already generated slugs.
     */
    private slugs: string[] = [];

    /**
     * Initializes a new instance of the `Slugifier` class.
     */
    public constructor()
    {
    }

    /**
     * Gets or sets the already generated slugs.
     */
    protected get Slugs(): string[]
    {
        return this.slugs;
    }
    protected set Slugs(value: string[])
    {
        this.slugs = value;
    }

    /**
     * Slugifies a text.
     * 
     * @param text
     * The text that is to be slugified.
     */
    public CreateSlug(text: string): string
    {
        let baseName = this.Slugify(text);

        let counter = 1;
        let slug = baseName;

        while (this.Slugs.includes(slug))
        {
            slug = `${baseName}-${++counter}`;
        }

        this.Slugs.push(slug);
        return slug;
    }

    /**
     * Slugifies a text.
     * 
     * @param text
     * The text that is to be slugified.
     */
    protected Slugify(text: string): string
    {
        return Transliteration.slugify(
            text,
            {
                lowercase: true,
                separator: "-",
                ignore: []
            });
    }
}

// build.rs
use std::path::Path;
use std::process::Command;
use std::env;

fn main() {
    let out_dir = env::var("OUT_DIR").unwrap();
    let debug = env::var("DEBUG").unwrap();

    let mut ispc_args = vec!["src/say_hello.ispc", "--pic"];
    if debug == "true" {
        ispc_args.push("-g");
    }
    // Invoke ISPC to compile our code
    let ispc_status = Command::new("ispc").args(&ispc_args[..])
        .args(&["-o", &format!("{}/say_hello.o", out_dir)])
        .status().unwrap();
    if !ispc_status.success() {
        panic!("ISPC compilation failed");
    }
    // Place our code into a static library we can link against
    let link_status = Command::new("ar").args(&["crus", "libsay_hello.a", "say_hello.o"])
        .current_dir(&Path::new(&out_dir))
        .status().unwrap();
    if !link_status.success() {
        panic!("Linking ISPC code into archive failed");
    }
    println!("cargo:rustc-flags=-L native={}", out_dir);
}

