#include "poweroff.h"
#include "inttypes.h"

void poweroff(void) {
  volatile uint32_t* pUnlockResetReg = (uint32_t*)0x10000020;
  volatile uint32_t* pResetReg = (uint32_t*)0x10000040;

  // If qemu is executed with -no-reboot option then
  // resetting the board will cause qemu to exit
  // and it won't be necessary to ctrl-a, x to exit.
  // See http://lists.nongnu.org/archive/html/qemu-discuss/2015-10/msg00057.html

  // For arm926ej-s you unlock the reset register
  // then reset the board, I'm resetting to level 6

  *pUnlockResetReg = 0xA05F;
  *pResetReg = 0x106;
}

// src/components/UISrefActive.tsx
import {Component, PropTypes, cloneElement, ValidationMap} from 'react';
import * as classNames from 'classnames';
import UIRouterReact, { UISref } from '../index';
import {UIViewAddress} from "./UIView";
import {find} from '../utils';

export interface IProps {
    class?: string;
    children?: any;
}

export class UISrefActive extends Component<IProps,any> {
    uiSref;

    static propTypes = {
        class: PropTypes.string.isRequired,
        children: PropTypes.element.isRequired
    }

    static contextTypes: ValidationMap<any> = {
        parentUIViewAddress: PropTypes.object
    }

    componentWillMount () {
        const child = this.props.children;
        this.uiSref = find(child, component => {
            return typeof component.type === 'function' && component.type.name === 'UISref';
        });
    }

    isActive = () => {
        let parentUIViewAddress: UIViewAddress = this.context['parentUIViewAddress'];
        let {to, params} = this.uiSref.props, {stateService} = UIRouterReact.instance;
        let state = stateService.get(to, parentUIViewAddress.context) || { name: to };
        return this.uiSref && (stateService.is(state.name, params) || stateService.includes(state.name, params));
    }

    render () {
        let isActive = this.isActive();
        return (
            !isActive
                ? this.props.children
                : cloneElement(this.props.children, Object.assign({}, this.props.children.props, {
                    className: classNames(this.props.children.props.className, this.props.class)
                }))
        );
    }
}

// providers/systemd/get_test.go
package systemd_test

import (
	"fmt"

	"github.com/mistifyio/mistify/acomm"
	"github.com/mistifyio/mistify/providers/systemd"
)

func (s *sd) TestGet() {
	tests := []struct {
		name string
		err  string
	}{
		{"", "missing arg: name"},
		{"doesnotexist.service", "unit not found"},
		{"dbus.service", ""},
	}

	for _, test := range tests {
		args := &systemd.GetArgs{test.name}
		argsS := fmt.Sprintf("%+v", test)

		req, err := acomm.NewRequest("zfs-exists", "unix:///tmp/foobar", "", args, nil, nil)
		s.Require().NoError(err, argsS)

		res, streamURL, err := s.systemd.Get(req)
		s.Nil(streamURL, argsS)
		if test.err == "" {
			if !s.NoError(err, argsS) {
				continue
			}
			result, ok := res.(*systemd.GetResult)
			if !s.True(ok, argsS) {
				continue
			}
			if !s.NotNil(result.Unit, argsS) {
				continue
			}
			s.Equal(test.name, result.Unit.Name, argsS)
		} else {
			s.EqualError(err, test.err, argsS)
		}
	}
}

