#import <Foundation/Foundation.h>

/**
 The error level for logging non-critical errors using `HLError()`.
*/
typedef NS_ENUM(NSInteger, HLErrorLevel) {
  /**
   Errors.
  */
  HLLevelError,
  /**
   Warnings.
  */
  HLLevelWarning,
  /**
   Information.
  */
  HLLevelInfo,
};

/**
 Logs a non-critical error.
*/
static inline void
HLError(HLErrorLevel level, NSString *message)
{
  // TODO: This is a placeholder for a better mechanism for non-critical error logging,
  // e.g. CocoaLumberjack.
  NSString *levelLabel;
  switch (level) {
    case HLLevelInfo:
      levelLabel = @"INFO";
      break;
    case HLLevelWarning:
      levelLabel = @"WARNING";
      break;
    case HLLevelError:
      levelLabel = @"ERROR";
      break;
  }
  NSLog(@"%@: %@", levelLabel, message);
}

// source/types/itemList.ts
import * as _ from 'lodash';

export interface IItem {
    value: number;
    name: string;
    display: string;
}

export interface IItemList<TItemType extends IItem> {
	get(value: number | string): TItemType;
	all(): TItemType[];
}

export class ItemList<TItemType extends IItem> implements IItemList<TItemType> {
	private items: TItemType[];

	setItems(items: TItemType[]): void {
		this.items = items;
	}

	get(value: number | string): TItemType {
		var predicate: { (item: TItemType): boolean };

		if (typeof value === 'string') {
			predicate = (item: TItemType): boolean => {
				return (item.name === value);
			};
		} else {
			predicate = (item: TItemType): boolean => {
				return (item.value === value);
			};
		}

		return _.find(this.items, predicate);
	}

	all(): TItemType[] {
		return this.items;
	}
}

export class SortedItemList<TItemType extends IItem> extends ItemList<TItemType> {
	setItems(items: TItemType[]): void {
		super.setItems(_.sortBy(items, x => x.display));
	}
}

