          m_validPos == rhs.m_validPos &&
          m_searchMode == rhs.m_searchMode);
}

string DebugPrint(SearchParams const & params)
{
  string s("search::SearchParams: ");
  s = s + "Query = " + params.m_query;
  return s;
}

