func createUserPrompt() {
	// if alreadyUser {
	// 	confirm
	// }

	// scan
	var name, password string
	s := bufio.NewScanner(os.Stdin)

	fmt.Print("New User's Name: ")
	s.Scan()
	name = strings.ToLower(s.Text())

	fmt.Print("Password: ")
	s.Scan()
	password = s.Text()

	user, err := CreateUser(name, password)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return
	}

