@@ -0,0 +1,56 @@
+#include <stdint.h>
+#include <string.h>
+#include <stdio.h>
+#include <sys/types.h>
+
+
+static int UUID_SIZE = 16;
+char toHexChar(int b) {
+    char c;
+    if(b < 10)
+        c = '0' + b;
+    else
+        c = 'A' + b - 10;
+    return c;
+}
+int main(int argc, char **argv) {
+    int b = (0xa4 & 0xf0) >> 4;
+    printf("c0=%c, %d\n", toHexChar(b), b);
+    b = (0xa4 & 0x0f);
+    printf("c1=%c, %d\n", toHexChar(b), b);
+    // The raw data from the manufacturer's data packate
+    uint8_t data[] = {0x4c,0x0,
+            0x2,0x15,
+            0xa4,0x95,0xde,0xad,0xc5,0xb1,0x4b,0x44,0xb5,
+            0x12,0x13,0x70,0xf0,0x2d,0x74,0xde,0x30,0x39,0xff,0xff,
+            0xc5};
+    // Get the manufacturer code from the first two octets
+    int index = 0;
+    int manufacturer = 256 * data[index++] + data[index++];
+
+    // Get the first octet of the beacon code
+    int code = 256 * data[index++] + data[index++];
+
+    // Get the proximity uuid
+    char uuid[UUID_SIZE+1];
+    int n;
+    for(n = 0; n < UUID_SIZE; n += 2, index ++) {
+        int b0 = (data[index] & 0xf0) >> 4;
+        int b1 = data[index] & 0x0f;
+        char c0 = toHexChar(b0);
+        char c1 = toHexChar(b1);
+        uuid[n] = c0;
+        uuid[n+1] = c1;
+    }
+    uuid[UUID_SIZE] = '\0';
+
+    // Get the beacon major id
+    int major = 256 * data[index++] + data[index++];
+    // Get the beacon minor id
+    int minor = 256 * data[index++] + data[index++];
+
+    // Get the transmitted power, which is encoded as the 2's complement of the calibrated Tx Power
+    int power = data[index] - 256;
+
+    printf("uuid=%s, manufacturer=%d, code=%d, major=%d, minor=%d, power=%d\n", uuid, manufacturer, code, major, minor, power);
+}

commit 6e6c92918d5530daf2a482aa5a747434d9c60ae1

    Add algorithm for Inverse FFT

Add algorithm for Inverse FFT

diff --git a/InverseFastFourierTransform/C++/Inverse_FFT.cpp b/InverseFastFourierTransform/C++/Inverse_FFT.cpp
--- a/InverseFastFourierTransform/C++/Inverse_FFT.cpp
+++ b/InverseFastFourierTransform/C++/Inverse_FFT.cpp
@@ -0,0 +1,85 @@
+/*
+* @author Abhishek Datta
+* @github_id abdatta
+* @since 15th October, 2017
+*
+* The following algroithm takes complex coeeficients
+* and calculates its inverse discrete fourier transform
+*/
+
+#include <complex>
+#include <iostream>
+#include <iomanip>
+#include <valarray>
+ 
+const double PI = std::acos(-1);
+ 
+typedef std::complex<double> Complex;
+typedef std::valarray<Complex> CArray;
+
+// recursive fft (in-place)
+void fft(CArray& x)
+{
+    const size_t N = x.size();
+    if (N <= 1) return;
+ 
+    // divide
+    CArray even = x[std::slice(0, N/2, 2)];
+    CArray  odd = x[std::slice(1, N/2, 2)];
+ 
+    // conquer
+    fft(even);
+    fft(odd);
+ 
+    // combine
+    for (size_t k = 0; k < N/2; ++k)
+    {
+        Complex t = std::polar(1.0, 2 * PI * k / N) * odd[k];
+        x[k    ] = even[k] + t;
+        x[k+N/2] = even[k] - t;
+    }
+}
+ 
+// inverse fft (in-place)
+void ifft(CArray& x)
+{
+    // conjugate the complex numbers
+    x = x.apply(std::conj);
+ 
+    // forward fft
+    fft( x );
+ 
+    // conjugate the complex numbers again
+    x = x.apply(std::conj);
+ 
+    // scale the numbers
+    x /= x.size();
+}
+ 
+int main()
+{
+	int t; // no. of test cases to try on
+	std::cin>>t;
+	while(t--)
+	{
+		int n; // n is for order of the polynomial
+		std::cin>>n;
+	    Complex test[n];
+	    for (int i = 0; i < n; ++i)
+	    {
+	    	double real, imag;
+	    	std::cin>>real>>imag; // reading each coefficient as a complex number
+	    	test[i].real(real); // setting real part to real
+	    	test[i].imag(imag); // and imaginary part to imaginary
+	    }
+
+	    CArray data(test, n);
+
+	    ifft(data);
+	 
+	    for (int i = 0; i < n; ++i)
+	    {
+	        std::cout << std::fixed << std::setprecision(6) << data[i].real() << " " << data[i].imag() << std::endl;
+	    }
+	}
+}

