#define MAX_COUNT 100000

const char alphanum[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

void gen_random(char *s, const int len)
{
	int i;
	for (i = 0; i < len; i++) {
		s[i] = alphanum[rand() % (sizeof(alphanum) - 1)];
	}
	s[len] = 0;
}

int main()
{
	int i;
	FILE *f;
	char fname[15];
	time_t start, end;

	time(&start);
	for (i = 0; i < MAX_COUNT; i++) {
		gen_random(fname, 15);
