func (e *UnknownCFTypeError) Error() string {
	cfStr := C.CFCopyTypeIDDescription(e.CFTypeID)
	str := convertCFStringToString(cfStr)
	cfRelease(cfTypeRef(cfStr))
	return "plist: unknown CFTypeID " + strconv.Itoa(int(e.CFTypeID)) + " (" + str + ")"
}

