        std::ifstream f;
        std::stringstream ss;

        f.open(file, std::ios::in | std::ios::binary);

        if (f.fail()) printf("doh\n");
        ss << f.rdbuf();
        if (!f && !f.eof()) printf("doh\n");
        f.close();

        return ss.str();
}


